 public static object Prepare(string take){Guard();if(!string.IsNullOrEmpty(SessionState.GetString(K+".Snapshot","")))throw new Exception("Cleanup prior fixture first");if(Pixel360Rendering.IsActive||UnityEngine.Object.FindObjectsByType<UnityEngine.Rendering.Volume>(FindObjectsSortMode.None).Length!=0)throw new Exception("Preserve active rendering state");foreach(var key in new[]{"LowGraphicsDefaultV1","ShadowDistanceV2","ShadowDistanceV3"})if(PlayerPrefs.GetInt("DarkBrine.Settings."+key,0)!=1)throw new Exception("Migration preferences must already be initialized");
 var snap=new Snapshot{pipeline=QualitySettings.renderPipeline?QualitySettings.renderPipeline.GetInstanceID():0,mips=QualitySettings.globalTextureMipmapLimit,aniso=(int)QualitySettings.anisotropicFiltering,vsync=QualitySettings.vSyncCount,fps=Application.targetFrameRate,screenW=Screen.width,screenH=Screen.height,mode=(int)Screen.fullScreenMode,cursor=(int)Cursor.lockState,lod=QualitySettings.lodBias,audio=AudioListener.volume,time=Time.timeScale,visible=Cursor.visible};SessionState.SetString(K+".Snapshot",Newtonsoft.Json.JsonConvert.SerializeObject(snap));SessionState.SetString(K+".Take",take);var lightGo=new GameObject("AUTO_QA settings shadow baseline",typeof(Light));lightGo.GetComponent<Light>().shadows=LightShadows.Soft;SessionState.SetInt(K+".Light",lightGo.GetInstanceID());var rows=new List<object>();var menu=Spawn();SessionState.SetString(K+".Factory",Newtonsoft.Json.JsonConvert.SerializeObject(Get(menu,"factoryDefaults")));SessionState.SetString(K+".Saved",Newtonsoft.Json.JsonConvert.SerializeObject(Get(menu,"saved")));SessionState.SetInt(K+".Owner",menu.gameObject.GetInstanceID());SessionState.SetInt(K+".Pipeline",QualitySettings.renderPipeline?QualitySettings.renderPipeline.GetInstanceID():0);
 menu.Open();Check(rows,PauseSettingsMenu.IsOpen&&Time.timeScale==0&&menu.overlay.blocksRaycasts,"Pause opens, freezes time and owns overlay");menu.enabled=false;Check(rows,!PauseSettingsMenu.IsOpen&&Mathf.Approximately(Time.timeScale,snap.time)&&menu.overlay.alpha==0&&!menu.overlay.blocksRaycasts,"Disabling owner releases pause and overlay");menu.enabled=true;menu.Resume();Time.timeScale=snap.time;
 menu.Open();var other=Spawn();UnityEngine.Object.DestroyImmediate(other.gameObject);Check(rows,PauseSettingsMenu.IsOpen&&Time.timeScale==0,"Destroying unrelated menu preserves active pause owner");menu.Resume();Time.timeScale=snap.time;
 menu.Open();var peer=Spawn();peer.Resume();Check(rows,PauseSettingsMenu.IsOpen&&Time.timeScale==0,"Unrelated Resume cannot release another owner");UnityEngine.Object.DestroyImmediate(peer.gameObject);menu.Resume();Time.timeScale=snap.time;
 menu.Open();menu.resumeButton.onClick.Invoke();Check(rows,!PauseSettingsMenu.IsOpen&&Mathf.Approximately(Time.timeScale,snap.time),"Authored Resume button closes its menu");
