 public static object AfterReload(){Guard();var rows=new List<object>();var menu=(EditorUtility.EntityIdToObject(SessionState.GetInt(K+".Owner",0)) as GameObject).GetComponent<PauseSettingsMenu>();var snap=Read();Check(rows,!AppDomain.CurrentDomain.GetAssemblies().Any(a=>a.GetName().Name==SessionState.GetString(K+".Assembly","")),"Actual reload unloaded preparation assembly");Check(rows,!PauseSettingsMenu.IsOpen&&Mathf.Approximately(Time.timeScale,snap.time)&&menu.overlay.alpha==0,"Reload releases prior pause and overlay");string openError=null;try{menu.Open();}catch(Exception e){openError=e.GetType().Name+": "+e.Message;}Check(rows,openError==null&&PauseSettingsMenu.IsOpen&&Time.timeScale==0&&menu.overlay.alpha==1,"Menu opens after reload with rehydrated settings");menu.resumeButton.onClick.Invoke();Check(rows,!PauseSettingsMenu.IsOpen&&Mathf.Approximately(Time.timeScale,snap.time)&&menu.overlay.alpha==0,"Resume binding survives actual reload");
 Check(rows,Newtonsoft.Json.JsonConvert.SerializeObject(Get(menu,"factoryDefaults"))==SessionState.GetString(K+".Factory","")&&Newtonsoft.Json.JsonConvert.SerializeObject(Get(menu,"saved"))==SessionState.GetString(K+".Saved",""),"Reload preserves saved settings and factory defaults");var light=(EditorUtility.EntityIdToObject(SessionState.GetInt(K+".Light",0)) as GameObject).GetComponent<Light>();var lightCache=(Dictionary<Light,LightShadows>)Get(menu,"originalLightShadows");Check(rows,lightCache.TryGetValue(light,out var originalShadow)&&originalShadow==LightShadows.Soft,"Reload restores original light-shadow cache");
 if(openError==null){menu.enabled=false;menu.Open();Check(rows,!PauseSettingsMenu.IsOpen,"Disabled menu rejects public Open");menu.enabled=true;menu.mainMenuSettingsOnly=true;menu.OpenSettingsFromMainMenu();Check(rows,PauseSettingsMenu.IsOpen&&menu.settingsPanel.activeSelf&&!menu.homePanel.activeSelf,"Title-screen settings open directly to settings");menu.Resume();Check(rows,!PauseSettingsMenu.IsOpen&&Cursor.lockState==CursorLockMode.None&&Cursor.visible,"Title-screen Resume preserves visible cursor");menu.mainMenuSettingsOnly=false;for(int i=0;i<3;i++){menu.enabled=false;menu.enabled=true;}menu.Open();var option=menu.options.Find(x=>x.key=="difficulty");var draft=Get(menu,"draft");int old=(int)draft.GetType().GetField("difficulty").GetValue(draft);option.button.onClick.Invoke();draft=Get(menu,"draft");Check(rows,(int)draft.GetType().GetField("difficulty").GetValue(draft)==(old+1)%3,"Reenable does not duplicate option handlers");menu.Resume();}
 Check(rows,QualitySettings.renderPipeline==(RenderPipelineAsset)Get(menu,"runtimePipelineAsset")&&QualitySettings.renderPipeline!=null,"Runtime pipeline remains owned after reload");return Write(SessionState.GetString(K+".Take","")+"-after",new{rows,openError,frame=Time.frameCount});}
 public static object Cleanup(){var snap=Read();foreach(var key in new[]{"Owner","Actor","Light"}){var go=EditorUtility.EntityIdToObject(SessionState.GetInt(K+"."+key,0)) as GameObject;if(go)UnityEngine.Object.DestroyImmediate(go);SessionState.EraseInt(K+"."+key);}Pixel360Rendering.ReleaseCurrent();var owned=EditorUtility.EntityIdToObject(SessionState.GetInt(K+".Pipeline",0));QualitySettings.renderPipeline=EditorUtility.EntityIdToObject(snap.pipeline) as RenderPipelineAsset;if(owned&&owned.GetInstanceID()!=snap.pipeline)UnityEngine.Object.DestroyImmediate(owned);QualitySettings.globalTextureMipmapLimit=snap.mips;QualitySettings.anisotropicFiltering=(AnisotropicFiltering)snap.aniso;QualitySettings.vSyncCount=snap.vsync;QualitySettings.lodBias=snap.lod;Application.targetFrameRate=snap.fps;AudioListener.volume=snap.audio;Time.timeScale=snap.time;Cursor.lockState=(CursorLockMode)snap.cursor;Cursor.visible=snap.visible;if(Screen.width!=snap.screenW||Screen.height!=snap.screenH||Screen.fullScreenMode!=(FullScreenMode)snap.mode)Screen.SetResolution(snap.screenW,snap.screenH,(FullScreenMode)snap.mode);SessionState.EraseString(K+".Factory");SessionState.EraseString(K+".Saved");SessionState.EraseString(K+".Snapshot");SessionState.EraseString(K+".Take");SessionState.EraseString(K+".Assembly");SessionState.EraseInt(K+".Pipeline");return new{restored=true,pipeline=QualitySettings.renderPipeline?QualitySettings.renderPipeline.GetInstanceID():0};}

 public static async Task<object> NativeControls(string take){Guard();if(CombatFeelPreview.Player||SessionState.GetBool("CombatCombinationTests",false))throw new Exception("Input fixture already owned");Prepare(take+"-setup");var menu=(EditorUtility.EntityIdToObject(SessionState.GetInt(K+".Owner",0)) as GameObject).GetComponent<PauseSettingsMenu>();menu.Resume();var placeholder=EditorUtility.EntityIdToObject(SessionState.GetInt(K+".Actor",0)) as GameObject;if(placeholder)UnityEngine.Object.DestroyImmediate(placeholder);SessionState.EraseInt(K+".Actor");
 var oldKeyboard=Keyboard.current;var oldMouse=Mouse.current;var oldSettings=InputSystem.settings;var oldFlags=oldSettings.hideFlags;var states=InputSystem.devices.Select(d=>(device:d,enabled:d.enabled)).ToArray();InputSettings settings=null;Keyboard keyboard=null;Mouse mouse=null;Key[] held=Array.Empty<Key>();var rows=new List<object>();var errors=new List<string>();string error=null;int firstFrame=Time.frameCount;Action inject=()=>{if(keyboard==null||InputState.currentUpdateType!=InputUpdateType.Dynamic)return;keyboard.MakeCurrent();mouse.MakeCurrent();InputSystem.QueueStateEvent(keyboard,new KeyboardState(held));InputSystem.QueueStateEvent(mouse,new MouseState());};Application.LogCallback logger=(m,s,l)=>{if(l==LogType.Exception||l==LogType.Error)errors.Add(m);};
 async Task Frames(int count){int target=Time.frameCount+count;var limit=DateTime.UtcNow.AddSeconds(8);while(Time.frameCount<target){if(!Application.isPlaying||DateTime.UtcNow>limit)throw new Exception("Native frames stalled");await Task.Delay(5);}}
 async Task Tap(params Key[] keys){held=keys;await Frames(4);held=Array.Empty<Key>();await Frames(4);}
 try{SessionState.SetBool("CombatCombinationTests",true);if(oldFlags==HideFlags.HideAndDontSave)oldSettings.hideFlags&=~HideFlags.NotEditable;settings=UnityEngine.Object.Instantiate(oldSettings);settings.hideFlags=HideFlags.DontSave;settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;InputSystem.settings=settings;CombatFeelPreview.Spawn();menu.enabled=true;CombatFeelPreview.Target.transform.position+=Vector3.forward*60;foreach(var d in states)if((d.device is Keyboard||d.device is Mouse)&&d.enabled)InputSystem.DisableDevice(d.device);keyboard=InputSystem.AddDevice<Keyboard>("AutoQaUiKeyboard");mouse=InputSystem.AddDevice<Mouse>("AutoQaUiMouse");InputSystem.onBeforeUpdate+=inject;Application.logMessageReceived+=logger;var input=CombatFeelPreview.Player.GetComponent<PlayerInput>();InputUser.PerformPairingWithDevice(keyboard,input.user);InputUser.PerformPairingWithDevice(mouse,input.user);input.ActivateInput();await Frames(12);var gear=CombatFeelPreview.Player.GetComponent<SahurLoadoutUI>();var map=CombatFeelPreview.Player.GetComponent<IslandMapUI>();var death=CombatFeelPreview.Player.GetComponent<PlayerDeathRespawn>();var health=CombatFeelPreview.Player.GetComponent<PlayerHealth>();int mask=CombatFeelPreview.Camera.cullingMask;
 await Tap(Key.Escape);Check(rows,PauseSettingsMenu.IsOpen&&Time.timeScale==0,"Queued Esc opens pause");await Tap(Key.Escape);Check(rows,!PauseSettingsMenu.IsOpen&&Time.timeScale>0,"Queued Esc resumes gameplay");await Tap(Key.I);Check(rows,gear.PanelVisible&&Time.timeScale==0,"Queued I opens equipment");await Tap(Key.Escape);Check(rows,!gear.PanelVisible&&!PauseSettingsMenu.IsOpen&&Time.timeScale>0,"Esc closes equipment without reopening pause");await Tap(Key.Escape);Check(rows,PauseSettingsMenu.IsOpen,"Next Esc can open pause after equipment consumes prior frame");menu.resumeButton.onClick.Invoke();await Frames(3);
 await Tap(Key.M);Check(rows,map.PanelVisible&&Time.timeScale==0&&CombatFeelPreview.Camera.cullingMask==0,"Queued M opens map and suspends rendering");await Tap(Key.I);Check(rows,map.PanelVisible&&!gear.PanelVisible,"Map blocks equipment hotkey");await Tap(Key.Escape);Check(rows,!map.PanelVisible&&!PauseSettingsMenu.IsOpen&&Time.timeScale>0&&CombatFeelPreview.Camera.cullingMask==mask,"Esc closes map without pause overlap and restores camera");await Tap(Key.I);await Tap(Key.M);Check(rows,gear.PanelVisible&&!map.PanelVisible,"Equipment blocks map hotkey");await Tap(Key.Escape);await Tap(Key.I,Key.M);Check(rows,map.PanelVisible&&!gear.PanelVisible&&!PauseSettingsMenu.IsOpen,"Simultaneous M/I yields one modal owner");
 health.currentHealth=0;death.Die();await Frames(4);Check(rows,death.IsDead&&!map.PanelVisible&&!gear.PanelVisible&&Time.timeScale==0&&CombatFeelPreview.Camera.cullingMask==mask,"Death closes map and retains death pause");await Tap(Key.Escape);Check(rows,death.IsDead&&!PauseSettingsMenu.IsOpen,"Death blocks pause hotkey");if(HealingPackSupply.Remaining!=HealingPackSupply.Total)throw new Exception("Preserve non-full healing ledger");await Tap(Key.Enter);Check(rows,!death.IsDead&&health.currentHealth==health.maxHealth&&Time.timeScale>0,"Queued Enter respawns from death UI");await Tap(Key.Escape);Check(rows,PauseSettingsMenu.IsOpen,"Pause input works after respawn");menu.Resume();var duplicate=Spawn();menu.Open();await Tap(Key.Escape);Check(rows,!PauseSettingsMenu.IsOpen&&Time.timeScale>0,"One Esc closes pause without another instance reopening it");duplicate.Resume();menu.Resume();UnityEngine.Object.DestroyImmediate(duplicate.gameObject);Check(rows,errors.Count==0,"No runtime errors during native UI sequence");}
 catch(Exception e){error=e.ToString();}finally{InputSystem.onBeforeUpdate-=inject;Application.logMessageReceived-=logger;if(keyboard!=null&&keyboard.added)InputSystem.RemoveDevice(keyboard);if(mouse!=null&&mouse.added)InputSystem.RemoveDevice(mouse);foreach(var d in states)if(d.device.added){if(d.enabled&&!d.device.enabled)InputSystem.EnableDevice(d.device);if(!d.enabled&&d.device.enabled)InputSystem.DisableDevice(d.device);}if(oldKeyboard!=null&&oldKeyboard.added)oldKeyboard.MakeCurrent();if(oldMouse!=null&&oldMouse.added)oldMouse.MakeCurrent();if(oldSettings){InputSystem.settings=oldSettings;oldSettings.hideFlags=oldFlags;}if(settings&&InputSystem.settings!=settings)UnityEngine.Object.DestroyImmediate(settings);CombatFeelPreview.Clear();SessionState.SetBool("CombatCombinationTests",false);Cleanup();}
 return Write(take,new{rows,error,errors,nativeFrames=Time.frameCount-firstFrame,settingsRestored=InputSystem.settings==oldSettings&&oldSettings.hideFlags==oldFlags,devicesRestored=states.All(d=>d.device.added&&d.device.enabled==d.enabled),currentDevicesRestored=Keyboard.current==oldKeyboard&&Mouse.current==oldMouse});}

